<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/csrf.php';require_once __DIR__.'/../includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('reserva.php');verify_csrf();$date=$_POST['delivery_date']??'';$qty=filter_var($_POST['quantity']??0,FILTER_VALIDATE_INT);$phone=trim($_POST['phone']??'');if(!$date||!$qty||$qty<1||!$phone){flash('error','Completa los datos de la reserva.');redirect('reserva.php');}$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT available_quantity FROM availability WHERE delivery_date=? FOR UPDATE');$q->execute([$date]);$available=$q->fetchColumn();if($available!==false && $qty>$available)throw new RuntimeException('No hay disponibilidad suficiente.');$s=$pdo->prepare('INSERT INTO reservations(user_id,customer_name,phone,email,delivery_date,quantity,notes) VALUES(?,?,?,?,?,?,?)');$s->execute([user()['id'],trim($_POST['customer_name']),$phone,filter_var($_POST['email'],FILTER_VALIDATE_EMAIL),$date,$qty,trim($_POST['notes']??'')]);if($available!==false){$u=$pdo->prepare('UPDATE availability SET available_quantity=available_quantity-? WHERE delivery_date=?');$u->execute([$qty,$date]);}$pdo->commit();flash('success','Reserva creada correctamente.');redirect('dashboard.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage()==='No hay disponibilidad suficiente.'?$e->getMessage():'No se pudo guardar la reserva.');redirect('reserva.php');}
